add(2213, 'Keywords: Caro; adversarial search; Alpha-Beta pruning; selective search; WebAssembly.', 'Use five focused index terms rather than an eight-item component inventory.', 'https://journals.ieeeauthorcenter.ieee.org/create-your-ieee-journal-article/create-the-text-of-your-article/structure-your-article/')
add(7042, 'PvP — Player versus player; two people share one application.', 'Define the standard expansion before the project-specific meaning.', project+'/CaroGame/src/game/behaviors/match/MatchController.ts')
